def walk(n, depth=0):
    if isinstance(n, dict):
        t=n.get('type')
        if t=='text':
            out.append(n.get('text',''))
        elif t=='heading':
            out.append('\n\n### '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
