            out.append('`'+n.get('code','')+'`')
        elif t=='reference':
            out.append('[ref]')
        for k,v in n.items():
            if k in ('inlineContent','text','type','code'): continue
            walk(v, depth+1)
    elif isinstance(n, list):
        for c in n: walk(c, depth)
