import json,re
def flat(p):
    d=json.load(open(p))
    out=[]
    def walk(n):
        if isinstance(n,dict):
            if n.get('type')=='text': out.append(n['text'])
            elif n.get('type')=='heading': out.append('\n[H]'+n.get('text','')+' ')
            elif n.get('type')=='codeVoice': out.append('`'+n.get('code','')+'`')
            for k,v in n.items():
                if k in ('text','type','code'): continue
                walk(v)
        elif isinstance(n,list):
            for c in n: walk(c)
    walk(d)
    return ' '.join(out)
for p in ['layout.json','multitasking.json','windows.json','adaptivity-and-layout.json']:
    t=flat(p)
    open(p+'.txt','w').write(t)
    print('=====',p,len(t))
    for kw in ['size class','minimum','pt ','point','half','third','quadrant','Stage Manager','Slide Over','Split View']:
        for m in re.finditer(kw,t):
            print('  ',kw,'::',t[max(0,m.start()-160):m.start()+200].replace('\n',' '))
            break
